import { createHash } from "node:crypto";
import { existsSync } from "node:fs";
import { mkdir, readFile, rename, writeFile } from "node:fs/promises";
import { dirname, join, relative } from "node:path";
import { agentikHome, memoryPaths } from "./home.ts";

/**
 * Tamper-evident memory. `memory/.seal.json` maps every memory file (`MEMORY.md`, `USER.md`,
 * `projects/<slug>/MEMORY.md`) to the sha256 of what agentik last wrote there. A file whose
 * content no longer matches was modified out of band — by a worker with a shell, by a stray
 * script — and is shown as `[BLOCKED: modified out of band]` until a human runs
 * `agentik memory reseal`; every agentik write to it is refused meanwhile, so the reviewer's
 * next write cannot launder the foreign entry. A file with no seal yet (first run, a fresh
 * home) is accepted and sealed silently.
 *
 * Limits, stated: this is tamper-EVIDENT, not tamper-proof. There is no HMAC because the key
 * would live in the same home as the files; a process that can edit MEMORY.md can edit the
 * seal. It catches mistakes and unprivileged prompt-injected writes, not a root attacker.
 *
 * Writes to the seal are serialized (module mutex) and atomic (tmp + rename): the three
 * snapshots of `buildContext` run in Promise.all.
 */

export type SealStatus = "sealed" | "unsealed" | "diverged";

export const SEAL_FILE = ".seal.json";

let chain: Promise<unknown> = Promise.resolve();
function locked<T>(fn: () => Promise<T>): Promise<T> {
  const next = chain.then(fn, fn);
  chain = next.catch(() => undefined);
  return next;
}

export function sealPath(home?: string): string {
  return join(memoryPaths(agentikHome(home)).memoryDir, SEAL_FILE);
}

/** The seal key of a memory file: its path relative to `memory/`. */
export function sealKey(file: string, home?: string): string {
  return relative(memoryPaths(agentikHome(home)).memoryDir, file).split("\\").join("/");
}

export function digest(content: string): string {
  return createHash("sha256").update(content).digest("hex");
}

async function readSeal(home?: string): Promise<Record<string, string>> {
  try {
    const raw = JSON.parse(await readFile(sealPath(home), "utf8")) as unknown;
    return raw && typeof raw === "object" && !Array.isArray(raw) ? (raw as Record<string, string>) : {};
  } catch {
    return {};
  }
}

async function writeSeal(seal: Record<string, string>, home?: string): Promise<void> {
  const path = sealPath(home);
  await mkdir(dirname(path), { recursive: true });
  const tmp = `${path}.tmp-${process.pid}-${Date.now()}`;
  await writeFile(tmp, `${JSON.stringify(seal, null, 2)}\n`, "utf8");
  await rename(tmp, path);
}

/** Record `content` as the sealed state of `key`. */
export function sealContent(key: string, content: string, home?: string): Promise<void> {
  return locked(async () => {
    const seal = await readSeal(home);
    seal[key] = digest(content);
    await writeSeal(seal, home);
  });
}

/** Seal a file as it is on disk (a rename, a migration, a human `reseal`); absent file → entry removed. */
export function sealFile(file: string, home?: string): Promise<SealStatus> {
  return locked(async () => {
    const seal = await readSeal(home);
    const key = sealKey(file, home);
    if (!existsSync(file)) {
      delete seal[key];
      await writeSeal(seal, home);
      return "unsealed";
    }
    seal[key] = digest(await readFile(file, "utf8"));
    await writeSeal(seal, home);
    return "sealed";
  });
}

export function unsealFile(file: string, home?: string): Promise<void> {
  return locked(async () => {
    const seal = await readSeal(home);
    delete seal[sealKey(file, home)];
    await writeSeal(seal, home);
  });
}

/**
 * Compare a file's content with its seal. `unsealed` (no entry) is accepted AND sealed here, so a
 * home that predates the seal is not flagged on its first read.
 */
export function checkSeal(file: string, content: string, home?: string): Promise<SealStatus> {
  return locked(async () => {
    const seal = await readSeal(home);
    const key = sealKey(file, home);
    const have = seal[key];
    const now = digest(content);
    if (have === undefined) {
      seal[key] = now;
      await writeSeal(seal, home);
      return "unsealed";
    }
    return have === now ? "sealed" : "diverged";
  });
}

export const DIVERGED_BODY = "[BLOCKED: modified out of band — agentik memory reseal to accept]";

import { createHash } from "node:crypto";
import { resolveWorkspaceRoot } from "./workspace.ts";
import { homedir } from "node:os";
import { basename, join, resolve } from "node:path";

const PROFILE_NAME = /^[a-z0-9][a-z0-9._-]*$/i;

/**
 * Profile home. `default` is `~/.agentik` itself (backwards compatible); any other name lives
 * under `~/.agentik/profiles/<name>`. Resolution order: explicit argument, then AGENTIK_PROFILE,
 * then `default`. A name that could escape the profiles directory is refused.
 */
export function resolveProfileHome(profile?: string): string {
  const name = (profile ?? process.env.AGENTIK_PROFILE ?? "").trim() || "default";
  const base = join(homedir(), ".agentik");
  if (name === "default") return base;
  if (!PROFILE_NAME.test(name) || name === "." || name === "..") {
    throw new Error(`invalid profile name "${name}" (allowed: ${PROFILE_NAME.source})`);
  }
  return join(base, "profiles", name);
}

/** `override` (usually --agentik-home) > AGENTIK_HOME > profile (--profile / AGENTIK_PROFILE / default). */
export function agentikHome(override?: string, profile?: string): string {
  return override || process.env.AGENTIK_HOME || resolveProfileHome(profile);
}

export function memoryPaths(home: string) {
  return {
    root: home,
    memoryDir: join(home, "memory"),
    hot: join(home, "memory", "MEMORY.md"),
    user: join(home, "memory", "USER.md"),
    /** One MEMORY.md per workspace, under `<slug>/` (see projectMemoryPath). */
    projectDir: join(home, "memory", "projects"),
    /** Legacy WARM store (read-only now; kept on disk after migration). */
    db: join(home, "memory", "notes.sqlite"),
    /** Searchable session log: one row per run, FTS5 unicode61 + trigram. */
    sessionsDb: join(home, "sessions.sqlite"),
    migratedMarker: join(home, "memory", ".migrated-v1"),
    pendingSkills: join(home, "pending", "skills"),
    /** Staged writes awaiting `agentik memory approve` (config memory.writeApproval). */
    pendingMemoryOps: join(home, "pending", "memory"),
    /** Staged skill_manage patch/create awaiting `agentik skills approve` (skills.writeApproval). */
    pendingSkillOps: join(home, "pending", "skills-ops"),
    skills: join(home, "skills"),
    /** Per-skill usage counters the curator reads: views, patches, who created it, last use. */
    skillUsage: join(home, "skills", ".usage.json"),
    skillSnapshots: join(home, "skills", ".snapshots"),
    curatorLedger: join(home, "skills", ".curator-ledger.json"),
    config: join(home, "config.json"),
    /** Code indexes, one sqlite per checkout (`<slug>.sqlite` + `<slug>.workspace`); a cache. */
    indexDir: join(home, "index"),
  };
}

/**
 * Project memory directory name for a workspace: readable AND collision-free. The basename is
 * lowercased and sanitized (`[^a-z0-9._-]` → `-`), then joined with the first 10 hex chars of
 * sha256 of the absolute path, e.g. `agentik-3f2a9c1b7e`. Two checkouts with the same basename
 * never share a file; the `.workspace` file next to it holds the full path for humans.
 */
export function projectSlug(workspace: string): string {
  return legacyProjectSlug(resolveWorkspaceRoot(resolve(workspace)));
}

/** The slug formula on a path as given (no root resolution): what pre-C4 files were named after. */
export function legacyProjectSlug(path: string): string {
  const abs = resolve(path);
  const base = basename(abs).toLowerCase().replace(/[^a-z0-9._-]/g, "-") || "root";
  const hash = createHash("sha256").update(abs).digest("hex").slice(0, 10);
  return `${base}-${hash}`;
}

export function projectMemoryPath(home: string, workspace: string): string {
  return join(memoryPaths(home).projectDir, projectSlug(workspace), "MEMORY.md");
}
